screen('dev-pull-request', dict(viewport='desktop', title='Code review with diff and checks', category='dashboard', type='screen', roles=['detail','editor'], style=['data-dense','minimal'], tags=['developer-tool','code','diff','status','avatar','desktop'],
  desc='A desktop pull-request review page. The header shows the PR title "Add semantic diff to replays", its number, an Open status pill, the branch pair and author. Tabs (Conversation, Commits 4, Checks, Files 6) sit above a two-column layout: a unified diff of one file with line numbers, removed lines tinted red and added lines tinted green, and an inline review comment thread; the right column lists reviewers with approval states, three checks (two passed, one running) and a primary "Merge" button disabled until checks finish. Built on {words}. Idea: the diff is the hero; status lives in a quiet rail beside it.'),
  '''<div style="height:100%;padding:26px 32px;display:flex;flex-direction:column;gap:14px">
  <div class="row g12"><h1 class="d2" style="font-size:26px">Add semantic diff to replays</h1><span class="small" style="font-size:20px">#412</span></div>
  <div class="row g8"><span class="tag">'''+ic('branch')+''' Open</span><span class="small"><b style="color:var(--text)">kenji</b> wants to merge <code style="font-family:var(--mono)">feat/semantic-diff</code> into <code style="font-family:var(--mono)">main</code></span></div>
  <div class="row g16" style="border-bottom:1px solid var(--line);font-size:14px;color:var(--muted)"><span style="padding-bottom:10px">Conversation</span><span>Commits 4</span><span>Checks 3</span><b style="color:var(--text);padding-bottom:10px;border-bottom:2px solid var(--accent)">Files 6</b></div>
  <div class="row g16" style="flex:1;align-items:stretch;min-height:0"><div class="card" style="flex:1;padding:0;overflow:hidden;font:12.5px/1.75 var(--mono)"><div class="row" style="padding:10px 14px;border-bottom:1px solid var(--line);font-family:var(--sans)"><b style="font-size:13.5px">src/replay/diff.ts</b><div class="sp"></div><span class="small"><span class="up">+18</span> <span class="down">−4</span></span></div>'''+''.join(f'<div class="row" style="gap:0;background:{bg}"><span style="width:44px;text-align:right;padding-right:10px;color:var(--muted)">{n}</span><span style="width:18px;color:var(--muted)">{m}</span><span style="white-space:pre">{t}</span></div>' for n,m,t,bg in [(12,' ','export function diffRuns(a: Run, b: Run) {',''),(13,'−','  return textDiff(a.output, b.output)','color-mix(in oklab,#E5625A 14%,transparent)'),(13,'+','  const claims = extractClaims(a, b)','color-mix(in oklab,#3DBF7F 14%,transparent)'),(14,'+','  return claims.map(compareMeaning)','color-mix(in oklab,#3DBF7F 14%,transparent)'),(15,' ','}',''),(16,' ','','')])+'''<div style="margin:6px 14px 14px 62px;padding:12px;border-radius:12px;background:var(--surface2);font-family:var(--sans);font-size:13.5px"><div class="row g8"><span class="av s"></span><b>ana</b><span class="small">2 min ago</span></div><p style="margin-top:6px">Nice — can we cache <code style="font-family:var(--mono)">extractClaims</code> per run? Replays call this a lot.</p></div></div>
   <aside style="width:300px;display:flex;flex-direction:column;gap:12px"><div class="card col g8"><span class="eyebrow">Reviewers</span>'''+''.join(f'<div class="row g8"><span class="av s" style="filter:hue-rotate({h}deg)"></span><span style="font-size:14px">{n}</span><div class="sp"></div><span class="small {c}">{s}</span></div>' for n,s,c,h in [('ana','Commented','',0),('omar','Approved','up',120)])+'''</div>
    <div class="card col g8"><span class="eyebrow">Checks</span>'''+''.join(f'<div class="row g8" style="font-size:14px"><span class="{c}">{i}</span>{n}<div class="sp"></div><span class="small">{t}</span></div>' for n,i,c,t in [('Unit tests','✓','up','1m 12s'),('Eval suite · support','✓','up','2m 40s'),('Typecheck','◌','','running')])+'''</div>
    <div class="sp"></div><button class="btn btn-p" style="opacity:.45">Merge pull request</button><span class="small" style="text-align:center">Waiting for 1 check</span></aside></div></div>''')

